"""The rest of the command reference: every `cartacolibri` command, in 8 languages (informal "tu")."""
LANGS = ["en", "ro", "fr", "it", "es", "pt", "de", "hu"]


def r(cmd, *t):
    assert len(t) == 8, cmd
    return (cmd, dict(zip(LANGS, t)))


